   return '<article class="qr-context-card'+(card.chant?' qr-context-mnemonic':'')+'" data-note-origin="'+esc(card.origin)+'">'+(showHeading?'<h5>'+coloredText(card.heading)+'</h5>':'')+body.map(p=>'<p'+(p.kind==='notes'?' class="lesson-annotation"':'')+'>'+coloredText(p.text)+'</p>').join('')+'</article>';
